package com.bidx.repository;
import com.bidx.model.*;import com.bidx.util.*;import org.w3c.dom.*;import java.nio.file.*;import java.time.*;import java.math.*;import java.util.*;
public class AuctionRepository {private final Path p=AppPaths.file("auctions.xml");public synchronized List<Auction> all(){Document d=XmlStore.load(p,"auctions");List<Auction> r=new ArrayList<>();NodeList ns=d.getElementsByTagName("auction");for(int i=0;i<ns.getLength();i++)r.add(read((Element)ns.item(i)));return r;} private Auction read(Element e){Auction a=new Auction();a.id=XmlStore.text(e,"id");a.sellerId=XmlStore.text(e,"sellerId");a.title=XmlStore.text(e,"title");a.description=XmlStore.text(e,"description");a.category=XmlStore.text(e,"category");a.condition=XmlStore.text(e,"condition");a.imagePath=XmlStore.text(e,"imagePath");a.notes=XmlStore.text(e,"notes");a.highestBidderId=XmlStore.text(e,"highestBidderId");a.winnerId=XmlStore.text(e,"winnerId");a.startingPrice=new BigDecimal(XmlStore.text(e,"startingPrice"));a.currentHighestBid=new BigDecimal(XmlStore.text(e,"currentHighestBid"));a.minimumIncrement=new BigDecimal(XmlStore.text(e,"minimumIncrement"));a.startAt=LocalDateTime.parse(XmlStore.text(e,"startAt"));a.endAt=LocalDateTime.parse(XmlStore.text(e,"endAt"));a.createdAt=LocalDateTime.parse(XmlStore.text(e,"createdAt"));a.updatedAt=LocalDateTime.parse(XmlStore.text(e,"updatedAt"));a.status=AuctionStatus.valueOf(XmlStore.text(e,"status"));return a;} public synchronized Auction find(String id){return all().stream().filter(a->a.id.equals(id)).findFirst().orElse(null);} public synchronized void insert(Auction a){Document d=XmlStore.load(p,"auctions");d.getDocumentElement().appendChild(element(d,a));XmlStore.save(d,p);} public synchronized void update(Auction a){Document d=XmlStore.load(p,"auctions");NodeList ns=d.getElementsByTagName("auction");for(int i=0;i<ns.getLength();i++){Element e=(Element)ns.item(i);if(XmlStore.text(e,"id").equals(a.id)){d.getDocumentElement().replaceChild(element(d,a),e);XmlStore.save(d,p);return;}}throw new IllegalArgumentException("Auction not found");} private Element element(Document d,Auction a){Element e=d.createElement("auction");Object[][] x={{"id",a.id},{"sellerId",a.sellerId},{"title",a.title},{"description",a.description},{"category",a.category},{"condition",a.condition},{"imagePath",a.imagePath},{"notes",a.notes},{"startingPrice",a.startingPrice},{"currentHighestBid",a.currentHighestBid},{"highestBidderId",a.highestBidderId},{"minimumIncrement",a.minimumIncrement},{"startAt",a.startAt},{"endAt",a.endAt},{"status",a.status},{"winnerId",a.winnerId},{"createdAt",a.createdAt},{"updatedAt",a.updatedAt}};for(Object[] y:x)XmlStore.put(d,e,(String)y[0],y[1]);return e;}}
